select  dif.Vendor_Id,
        dif.Source_Cd,
        dif.Vendor_Name,
        dif.Activation_Date,
        dif.Deactivation_Date,
        dif.Active_Ind,
        dif.Userid,
        dif.Add_Date,
        dif.Update_Date
  from  (
            select  dat.Vendor_Id,
                    'NEW' as Source_Cd,
                    dat.Vendor_Name,
                    dat.Activation_Date,
                    dat.Deactivation_Date,
                    dat.Active_Ind,
                    dat.Userid,
                    dat.Add_Date,
                    dat.Update_Date
              from   ( select * from new except select * from old ) dat
            union
            select  dat.Vendor_Id,
                    'OLD' as Source_Cd,
                    dat.Vendor_Name,
                    dat.Activation_Date,
                    dat.Deactivation_Date,
                    dat.Active_Ind,
                    dat.Userid,
                    dat.Add_Date,
                    dat.Update_Date
              from  ( select * from old except select * from new ) dat
        ) dif
 order
    by  dif.Vendor_Id,
        dif.Source_Cd
